// Keep the reading passage available during checkpoints, as in real reading tasks.
const originalMissionView=missionView,originalCheckpointView=checkpointView;
missionView=function(){return originalMissionView().replace('<h3>Read & listen: a real-life exchange</h3>',readingBlock(unitId)+'<h3>Read & listen: a real-life exchange</h3>');};
checkpointView=function(){return originalCheckpointView().replace('<div class="quizmeta">',`<details><summary>Reading texts for this checkpoint</summary>${readingBlock(unitId)}<h3>Conversation</h3>${units.find(u=>u.id===unitId).dialogue.map(([de])=>`<p lang="de">${esc(de)}</p>`).join('')}</details><div class="quizmeta">`);};
function readingBlock(id){const r=readings.find(x=>x.unit===id);return `<h3>Reading workshop: ${esc(r.title)}</h3><p class="lead">Read for the main idea, then find dates, people, prices and negation. Listen without looking on your second pass. Use the unit checkpoint to test your understanding.</p><div class="dialogue"><p lang="de">${esc(r.de)}</p><div class="controls">${audioButton(r.de)}<small>Device speech · try reading aloud first</small></div><details><summary>English support</summary><p>${esc(r.en)}</p></details></div>`;}
render();
